const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Singapore',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(new Date());

const today = `${parts.find(p => p.type === 'year').value}-${parts.find(p => p.type === 'month').value}-${parts.find(p => p.type === 'day').value}`;

const d = new Date(`${today}T00:00:00+08:00`);
d.setDate(d.getDate() - 370);
const startDate = d.toISOString().slice(0, 10);

return [{ json: { today_sgt: today, start_date: startDate } }];

const out = [];
for (const item of $input.all()) {
  if (Array.isArray(item.json)) out.push(...item.json);
  else if (Array.isArray(item.json.data)) out.push(...item.json.data);
  else if (Array.isArray(item.json.rows)) out.push(...item.json.rows);
  else out.push(item.json);
}
return [{
  json: {
    start_date: $('Build Reconstruction Params').first().json.start_date,
    today_sgt: $('Build Reconstruction Params').first().json.today_sgt,
    price_rows: out
  }
}];

const out = [];
for (const item of $input.all()) {
  if (Array.isArray(item.json)) out.push(...item.json);
  else if (Array.isArray(item.json.data)) out.push(...item.json.data);
  else if (Array.isArray(item.json.rows)) out.push(...item.json.rows);
  else out.push(item.json);
}
return [{
  json: {
    start_date: $('Wrap Price Rows').first().json.start_date,
    today_sgt: $('Wrap Price Rows').first().json.today_sgt,
    price_rows: $('Wrap Price Rows').first().json.price_rows || [],
    fmp_rows: out
  }
}];

const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const round2 = v => {
  if (v === null || v === undefined || !Number.isFinite(v)) return null;
  return Math.round(v * 100) / 100;
};

const clamp = (v, lo = 0, hi = 100) => Math.max(lo, Math.min(hi, v));

const priceRows = Array.isArray($json.price_rows) ? $json.price_rows : [];
const fmpRows = Array.isArray($json.fmp_rows) ? $json.fmp_rows : [];

const fmpByTicker = {};
for (const r of fmpRows) {
  if (!r || !r.ticker || !r.fiscal_date) continue;
  const ticker = String(r.ticker).toUpperCase();
  if (!fmpByTicker[ticker]) fmpByTicker[ticker] = [];
  fmpByTicker[ticker].push({ ...r, ticker, fiscal_date: String(r.fiscal_date) });
}
for (const ticker of Object.keys(fmpByTicker)) {
  fmpByTicker[ticker].sort((a, b) => a.fiscal_date.localeCompare(b.fiscal_date));
}

const pricesByTicker = {};
for (const p of priceRows) {
  if (!p || !p.ticker || !p.metric_date) continue;
  const ticker = String(p.ticker).toUpperCase();
  if (!pricesByTicker[ticker]) pricesByTicker[ticker] = [];
  pricesByTicker[ticker].push({ ...p, ticker, metric_date: String(p.metric_date) });
}
for (const ticker of Object.keys(pricesByTicker)) {
  pricesByTicker[ticker].sort((a, b) => a.metric_date.localeCompare(b.metric_date));
}

function latestFmpAsOf(ticker, date) {
  const arr = fmpByTicker[ticker] || [];
  if (!arr.length) return null;
  for (let i = arr.length - 1; i >= 0; i--) {
    if (arr[i].fiscal_date <= date) return arr[i];
  }
  return arr[0] || null;
}

function proxyToOverheatingScore(valuationProxy) {
  const p = toNum(valuationProxy);
  if (p === null) return null;
  return round2(clamp(50 + p));
}

function reversalScoreFromMomentumChange(change) {
  const c = toNum(change);
  if (c === null) return 50;
  return round2(clamp(50 - c * 2));
}

function signalLabel(score, change, reversalSignal) {
  if (reversalSignal) return 'Reversal Short Candidate';
  if (score === null || score === undefined) return 'No Score';
  if (score >= 70) return 'Expensive / Watch for Reversal';
  if (score >= 60) return 'Overvalued but Trend Intact';
  if (score >= 45) return 'Neutral';
  if (score >= 30) return 'Low Risk / Reasonable';
  return 'Potential Value / Depressed';
}

const reconstructed = [];

for (const [ticker, rows] of Object.entries(pricesByTicker)) {
  for (let i = 0; i < rows.length; i++) {
    const p = rows[i];
    const tradeDate = p.metric_date;
    const f = latestFmpAsOf(ticker, tradeDate);
    if (!f) continue;

    const valuationScore = toNum(f.valuation_score);
    const fundamentalScore = toNum(f.fundamental_score);
    const momentumScore = toNum(p.momentum_score);
    const overheatingScore = proxyToOverheatingScore(p.valuation_proxy);
    const prior = i >= 5 ? rows[i - 5] : null;
    const priorMomentum = prior ? toNum(prior.momentum_score) : null;
    const momentumChange5d = momentumScore !== null && priorMomentum !== null ? momentumScore - priorMomentum : null;
    const reversalScore = reversalScoreFromMomentumChange(momentumChange5d);

    let overall = null;
    if (valuationScore !== null && momentumScore !== null && overheatingScore !== null) {
      overall = (100 - valuationScore) * 0.70 + overheatingScore * 0.15 + reversalScore * 0.15;
    } else if (fundamentalScore !== null && momentumScore !== null && overheatingScore !== null) {
      overall = (100 - fundamentalScore) * 0.70 + overheatingScore * 0.15 + reversalScore * 0.15;
    }

    overall = round2(overall);
    if (overall === null) continue;

    const reversalSignal =
      overall >= 75 &&
      momentumChange5d !== null &&
      momentumChange5d < -5;

    reconstructed.push({
      run_date_sgt: tradeDate,
      ticker,
      momentum_score: round2(momentumScore),
      valuation_score: round2(valuationScore),
      overheating_score: round2(overheatingScore),
      ai_hype_score: null,
      overall_ai_risk_score: overall,
      momentum_change_5d: round2(momentumChange5d),
      reversal_score: round2(reversalScore),
      reversal_signal: reversalSignal,
      signal_label: signalLabel(overall, momentumChange5d, reversalSignal),
      explanation: [
        'Historical reconstructed score with hard momentum reversal filter.',
        'Score formula: 70% valuation risk + 15% overheating + 15% reversal risk.',
        'Reversal signal rule: overall_ai_risk_score >= 75 AND momentum_change_5d < -5.',
        `Price date ${tradeDate}.`,
        `FMP fiscal date used: ${f.fiscal_date}.`,
        `Momentum change 5 trading days: ${round2(momentumChange5d)}.`,
        `Reversal risk score: ${round2(reversalScore)}.`,
        `Reversal signal: ${reversalSignal}.`
      ].join(' ')
    });
  }
}

const chunkSize = 500;
const chunks = [];
for (let i = 0; i < reconstructed.length; i += chunkSize) {
  chunks.push({
    json: {
      rows: reconstructed.slice(i, i + chunkSize),
      row_count: Math.min(chunkSize, reconstructed.length - i),
      debug_price_rows: priceRows.length,
      debug_fmp_rows: fmpRows.length,
      debug_total_reconstructed: reconstructed.length
    }
  });
}

return chunks.length ? chunks : [{
  json: {
    rows: [],
    row_count: 0,
    debug_price_rows: priceRows.length,
    debug_fmp_rows: fmpRows.length,
    debug_total_reconstructed: 0,
    note: 'No historical score rows reconstructed.'
  }
}];
